INSERT INTO T_SCHEDULE_PUBLISH_LOG (ID, RECORD_ID, SCHEDULE_DATE, ORDER_NO, MACHINE_CODE, RECIPE_MATERIAL_CODE, RECIPE_VERSION_ID, RECIPE_TYPE, PLAN_QTY, SHIFT_CLASS_ID, PRODUCE_ORDER, INVOKE_RESULT, PUBLISH_RESULT, MIX_AREA, REMARK, CREATE_BY, CREATE_TIME ) SELECT NULL id, t.* FROM (
SELECT #{log.recordId,jdbcType= NUMERIC} RECORD_ID, #{log.scheduleDate,jdbcType= VARCHAR} SCHEDULE_DATE, #{log.orderNo,jdbcType= VARCHAR} ORDER_NO, #{log.machineCode,jdbcType= VARCHAR} MACHINE_CODE, #{log.recipeMaterialCode,jdbcType= VARCHAR} RECIPE_MATERIAL_CODE, #{log.recipeVersionId,jdbcType= INTEGER} RECIPE_VERSION_ID, #{log.recipeType,jdbcType= INTEGER} RECIPE_TYPE, #{log.planQty,jdbcType= INTEGER} PLAN_QTY, #{log.shiftClassId,jdbcType= INTEGER} SHIFT_CLASS_ID, #{log.produceOrder,jdbcType= INTEGER} PRODUCE_ORDER, hex(#{log.invokeResult,jdbcType= VARCHAR}) INVOKE_RESULT, #{log.publishResult,jdbcType= VARCHAR} PUBLISH_RESULT, #{log.mixArea,jdbcType= VARCHAR} MIX_AREA, #{log.remark,jdbcType= VARCHAR} REMARK, #{log.createBy,jdbcType= VARCHAR} CREATE_BY, #{log.createTime,jdbcType= TIMESTAMP} CREATE_TIME FROM dual
) T

