with temp_data as(
SELECT #{schedule.id, jdbcType = NUMERIC} ID, #{schedule.releaseStatus, jdbcType = VARCHAR} RELEASE_STATUS, #{schedule.midPublishStatus, jdbcType = VARCHAR} MID_PUBLISH_STATUS, #{schedule.nightPublishStatus, jdbcType = VARCHAR} NIGHT_PUBLISH_STATUS, #{schedule.dayPublishStatus, jdbcType = VARCHAR} DAY_PUBLISH_STATUS, #{schedule.publishSuccessCount, jdbcType = INTEGER} PUBLISH_SUCCESS_COUNT, #{schedule.newestPublishTime, jdbcType = DATE} NEWEST_PUBLISH_TIME, #{schedule.updateBy, jdbcType = VARCHAR} UPDATE_BY, #{schedule.updateTime, jdbcType = DATE} UPDATE_TIME
) update T_GLUE_SCHEDULE_RESULT a join temp_data b on a.id = b.id SET a.RELEASE_STATUS = '1', a.MID_PUBLISH_STATUS = b.MID_PUBLISH_STATUS, a.NIGHT_PUBLISH_STATUS = b.NIGHT_PUBLISH_STATUS, a.DAY_PUBLISH_STATUS = b.DAY_PUBLISH_STATUS, a.PUBLISH_SUCCESS_COUNT = b.PUBLISH_SUCCESS_COUNT, a.NEWEST_PUBLISH_TIME = b.NEWEST_PUBLISH_TIME, a.UPDATE_BY = b.UPDATE_BY, a.UPDATE_TIME = b.UPDATE_TIME where a.id = b.id
